        "title": "How My Students Think About AI",
        "author": "dvd",
        "siteName": "lesswrong.com",
        "category": "rss",
        "language": null,
        "readingTime": "14 mins",
        "readingMinutes": 14,
        "wordCount": 3459,
        "publishedDate": "2026-09-02",
